<script lang="ts">
 import {languageOverrides} from "./localization";
 import {onMount} from "svelte";
 import {displayPath} from "./storage";import type {DatabaseCatalog} from "./database-catalog";import {List,LayoutGrid,Database,Plus,FolderOpen,ArrowRight,X,Trash2,BookOpen} from "@lucide/svelte";import {translator} from "./i18n";
 export let onmanual:()=>void=()=>{};export let catalog:DatabaseCatalog;export let language:"ru"|"ro"|"en";export let active="default";export let onopen:(id:string)=>Promise<void>;export let onnew:(name:string)=>Promise<void>;export let onimport:()=>Promise<void>;export let onremove:(id:string)=>Promise<void>;export let onauto:(id:string|null)=>Promise<void>;
 let view="tiles";onMount(()=>{view=localStorage.getItem("openhau-database-view")==="list"?"list":"tiles";});
 function setView(value:string){view=value;localStorage.setItem("openhau-database-view",value);}
 let name="",busy=false,creating=false; $:t=translator(language,$languageOverrides);
 async function open(id:string){busy=true;try{await onopen(id);}finally{busy=false;}}
 async function remove(id:string){busy=true;try{await onremove(id);}finally{busy=false;}}
</script>
<div class="database-home">
 <aside><img src="/brand/logo-full.svg" alt="OpenHaU OPEN"/><button class="button" disabled={busy} onclick={()=>creating=true}><Plus size={18}/>{t("Создать базу","Creează o bază")}</button><button class="button secondary" disabled={busy} onclick={onimport}><FolderOpen size={18}/>{t("Добавить существующую","Adaugă o bază existentă")}</button><label>{t("При запуске…","La pornire…")}<select value={catalog.auto||""} onchange={e=>onauto(e.currentTarget.value||null)}><option value="">{t("Показывать выбор базы","Afișează alegerea bazei")}</option>{#each catalog.databases as db}<option value={db.id}>{db.name}</option>{/each}</select></label><button class="button secondary" onclick={onmanual}><BookOpen size={17}/>{t("Документация","Documentație")}</button></aside>
 <section><div class="database-heading"><h1>{t("Базы данных","Baze de date")}</h1><div class="database-view" aria-label={t("Вид","Vizualizare")}><button class:chosen={view==='tiles'} aria-pressed={view==='tiles'} title={t('Плитки','Dale')} onclick={()=>setView('tiles')}><LayoutGrid size={17}/></button><button class:chosen={view==='list'} aria-pressed={view==='list'} title={t('Список','Listă')} onclick={()=>setView('list')}><List size={17}/></button></div></div><div class="database-cards" class:database-list={view==='list'}>{#each catalog.databases as db}<article class="database-entry"><button class="database-card" disabled={busy} onclick={()=>open(db.id)}><Database size={32}/><strong>{db.name}</strong>{#if db.path}<small class="database-path" title={displayPath(db.path)}>{displayPath(db.path)}</small>{/if}{#if active===db.id}<small>{t("Текущая база","Baza curentă")}</small>{/if}<span><ArrowRight size={18}/>{t("Открыть","Deschide")}</span></button><button class="icon-button remove-database" disabled={busy} title={t("Убрать из списка · файл останется на диске","Elimină din listă · fișierul rămâne pe disc")} aria-label={t("Убрать из списка: ","Elimină din listă: ")+db.name} onclick={()=>remove(db.id)}><Trash2 size={17}/></button></article>{/each}{#if !catalog.databases.length}<p class="empty-list">{t("Добавьте существующую базу или создайте новую.","Adăugați o bază existentă sau creați una nouă.")}</p>{/if}</div></section>
</div>
{#if creating}<div class="create-backdrop" role="presentation"><div class="create-dialog" role="dialog" aria-modal="true" aria-label={t("Создать базу","Creează o bază")} tabindex="-1"><header><strong>{t("Создать базу","Creează o bază")}</strong><button class="icon-button" aria-label={t("Закрыть","Închide")} onclick={()=>creating=false}><X size={18}/></button></header><input aria-label={t("Название новой базы","Denumirea bazei noi")} bind:value={name}/><button class="button" disabled={busy||!name.trim()} onclick={async()=>{busy=true;try{await onnew(name);name="";creating=false;}finally{busy=false;}}}><Plus size={16}/>{t("Создать","Creează")}</button></div></div>{/if}






<style>
.database-home{display:grid;grid-template-columns:190px minmax(0,1fr);height:100%;min-width:0;overflow:hidden}.database-home aside{display:flex;flex-direction:column;gap:16px;padding:24px 14px;background:var(--sidebar);border-right:1px solid var(--border)}aside img{width:110px;margin:0 auto 20px;opacity:.8;filter:brightness(0)}:global(:root[data-theme="dark"]) aside img{filter:none}.database-home section{padding:24px;min-width:0;overflow-x:hidden;overflow-y:auto}.database-home h1{font-size:26px;font-weight:400;margin:0 0 30px}.create-backdrop{position:fixed;inset:0;z-index:30000;display:grid;place-items:center;background:#0005}.create-dialog{width:min(380px,90vw);display:grid;gap:18px;padding:24px;background:var(--surface);border:1px solid var(--border)}.create-dialog header{display:flex;justify-content:space-between;align-items:center}.database-cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:18px 0}.database-entry{position:relative;min-width:0}.remove-database{position:absolute;top:5px;right:5px}.database-card{width:100%;min-width:0;box-sizing:border-box;overflow-wrap:anywhere;display:flex;flex-direction:column;gap:16px;align-items:flex-start;text-align:left;padding:38px 16px 16px;background:transparent;border:1px solid transparent;color:var(--text);min-height:130px}.database-card:hover{border-color:var(--reveal-ink,#0002);background:var(--hover)}.database-card>:global(svg),.database-card>span{color:var(--accent)}.database-card span{display:flex;gap:8px;align-items:center}.database-home label{display:flex;flex-direction:column;gap:12px;max-width:440px}.database-path{max-width:100%;overflow-wrap:anywhere}.database-home small{color:var(--muted)}.database-home select,.database-home strong{min-width:0;max-width:100%;box-sizing:border-box}.empty-list{overflow-wrap:anywhere}.database-home aside .button{white-space:normal;text-align:left}
.database-home{width:100%;max-width:100%;box-sizing:border-box}.database-home aside{min-width:0;overflow-x:hidden;overflow-y:auto}.database-home section{width:100%;box-sizing:border-box}.database-home :global(*){min-width:0}.database-home aside label{margin-top:auto;font-size:12px}.database-home aside select{width:100%;text-overflow:ellipsis}.database-card strong,.database-path{white-space:normal;word-break:break-word}@media(max-width:480px){.database-cards{grid-template-columns:minmax(0,1fr)}}
.database-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:20px}.database-home .database-heading h1{margin:0}.database-view{display:flex;gap:4px}.database-view button{padding:8px;background:transparent;border:0;color:var(--text)}.database-view button.chosen{background:var(--hover);box-shadow:inset 0 -2px var(--accent)}.database-list{grid-template-columns:minmax(0,1fr)}.database-list .database-card{display:grid;grid-template-columns:28px minmax(0,1fr);gap:7px 12px;min-height:70px;padding:14px 35px 14px 12px}.database-list .database-card>:global(svg){grid-row:1/4;width:24px}.database-list .database-card strong,.database-list .database-card small,.database-list .database-card span{grid-column:2}.database-list .database-card span{font-size:11px}
</style>
